import random
import struct
from typing import List

# Generator for arbitrary binary data tailored to ENet fuzzing stubs that consume
# scatter/gather payloads, packet data, and range-coder input.
# Strategy:
# - Produce a compact container with concatenated chunks of varied characteristics.
# - Keep total size <= 4096 bytes.
# - Include varied content: ASCII text, zeroes, incremental bytes, high-entropy PRNG bytes,
#   repetitive patterns, and lengths ranging from empty to moderate.

MAX_TOTAL = 4096


def _rand_bytes(rng: random.Random, n: int) -> bytes:
    out = bytearray(n)
    i = 0
    while i < n:
        v = rng.getrandbits(32)
        for _ in range(4):
            if i >= n:
                break
            out[i] = v & 0xFF
            v >>= 8
            i += 1
    return bytes(out)


def _pattern_bytes(pattern: bytes, length: int) -> bytes:
    if length <= 0:
        return b""
    if len(pattern) == 0:
        return b"\x00" * length
    reps, rem = divmod(length, len(pattern))
    return pattern * reps + pattern[:rem]


def _ascii_block(rng: random.Random, length: int) -> bytes:
    choices = ([10, 13, 9, 0] * 2) + list(range(32, 127))
    return bytes(rng.choice(choices) for _ in range(length))


def _safe_randint(rng: random.Random, a: int, b: int) -> int:
    # Returns a value in [min(a,b), max(a,b)] even if b < a
    lo, hi = (a, b) if a <= b else (b, a)
    return rng.randint(lo, hi)


def _chunks_for_enet(rng: random.Random) -> List[bytes]:
    chunks: List[bytes] = []

    num_chunks = rng.randint(2, 6)

    remaining = MAX_TOTAL - 64  # reserve space for header/meta
    avg = max(32, remaining // max(2, num_chunks))

    for i in range(num_chunks):
        if remaining <= 0:
            break
        kind = rng.randrange(6)
        # Determine size safely given remaining capacity
        if i == 0:
            max0 = max(0, remaining)
            size = _safe_randint(rng, 0, min(256, max0))
        elif i == num_chunks - 1:
            # ensure lower bound doesn't exceed upper bound
            upper = min(1024, remaining)
            if upper <= 0:
                size = 0
            else:
                size = _safe_randint(rng, 16, upper)
        else:
            upper = min(avg * 2, remaining)
            if upper <= 0:
                size = 0
            else:
                size = _safe_randint(rng, 16, upper)
        size = max(0, min(size, remaining))

        if size == 0:
            blk = b""
        elif kind == 0:
            blk = _ascii_block(rng, size)
        elif kind == 1:
            blk = b"\x00" * size
        elif kind == 2:
            start = rng.randrange(256)
            blk = bytes((start + j) & 0xFF for j in range(size))
        elif kind == 3:
            pat_len = rng.choice([1, 2, 3, 4, 8])
            pat = _rand_bytes(rng, pat_len)
            blk = _pattern_bytes(pat, size)
        elif kind == 4:
            blk = _rand_bytes(rng, size)
        else:
            pfx_len = _safe_randint(rng, 0, size)
            pfx = _ascii_block(rng, pfx_len)
            sfx = _rand_bytes(rng, size - len(pfx))
            blk = pfx + sfx

        chunks.append(blk)
        remaining -= len(blk)
        if remaining <= 0:
            break

    # Add a few tiny edge-case chunks if space allows
    if remaining > 0:
        tiny_cases = [b"", b"A", b"\xFF", b"\x00\x01", b"\x7F\x80", b"END"]
        rng.shuffle(tiny_cases)
        to_take = _safe_randint(rng, 1, min(3, len(tiny_cases)))
        for t in tiny_cases[:to_take]:
            if remaining - len(t) <= 0:
                break
            chunks.append(t)
            remaining -= len(t)

    return chunks


def _serialize_container(chunks: List[bytes], rng: random.Random) -> bytes:
    # header: magic(4), count(1), flags(1), rsv(2)
    magic = b"bENt"
    count = min(15, len(chunks))
    flags = 0

    out = bytearray()
    out += magic
    out += struct.pack("<B", count)
    out += struct.pack("<B", flags)
    out += struct.pack("<H", 0)

    total = len(out)

    for i in range(count):
        d = chunks[i]
        if len(d) > 1024:
            d = d[:1024]
        seg = struct.pack("<H", len(d)) + d
        if total + len(seg) > MAX_TOTAL:
            break
        out += seg
        total += len(seg)

    # helper to add a block with length prefix safely
    def add_block(b: bytes) -> bool:
        nonlocal out, total
        seg = struct.pack("<H", len(b)) + b
        if total + len(seg) <= MAX_TOTAL:
            out += seg
            total += len(seg)
            return True
        return False

    # Append crafted flag combinations
    enet_flag_sets = [
        0,
        1 << 0,
        1 << 1,
        1 << 2,
        1 << 3,
        (1 << 0) | (1 << 3),
    ]
    for f in enet_flag_sets:
        if not add_block(struct.pack("<I", f)):
            break

    # Append payload-size-varied blocks
    for sz in [0, 1, 7, 32, 255]:
        if sz == 0:
            data = b""
        else:
            choice = rng.randrange(3)
            if choice == 0:
                data = _ascii_block(rng, sz)
            elif choice == 1:
                data = _pattern_bytes(b"\x00\xFF", sz)
            else:
                data = _rand_bytes(rng, sz)
        if not add_block(data):
            break

    return bytes(out)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    chunks = _chunks_for_enet(rng)
    data = _serialize_container(chunks, rng)

    if not data:
        data = _rand_bytes(rng, 32)

    if len(data) > MAX_TOTAL:
        data = data[:MAX_TOTAL]

    return data

import random
import string
from typing import List

# Generator for hostname strings for enet_address_set_host
# Produces NUL-terminated domain/hostname bytes.

MAX_TOTAL = 4096

ALNUM = string.ascii_lowercase + string.digits
ALNUM_HYPHEN = string.ascii_lowercase + string.digits + '-'

COMMON_TLDS = [
    "com","net","org","io","dev","local","test","example","edu","gov",
    "co","uk","de","jp","cn","ru","br","info","biz","xyz"
]

COMMON_HOSTS = [
    "localhost",
    "example.com",
    "intranet",
    "router",
    "gateway",
    "nas",
    "printer",
    "_service._tcp.local",
]

PUNY_EXAMPLES = [
    "xn--d1acpjx3f",             # пример (label only)
    "xn--bcher-kva",              # bücher
    "xn--caf-dma",                # café
    "xn--fiqs8s",                 # 中国
    "xn--fiq228c.com",            # 中文.com style
]


def rand_label(r: random.Random, min_len: int = 1, max_len: int = 20) -> str:
    # DNS label rules: 1-63 chars, a-z 0-9 hyphen, cannot start/end with hyphen.
    max_len = max(1, min(63, max_len))
    min_len = max(1, min(min_len, max_len))
    L = r.randint(min_len, max_len)
    if L == 1:
        return r.choice(string.ascii_lowercase + string.digits)
    start = r.choice(ALNUM)
    middle_len = max(0, L - 2)
    middle = ''.join(r.choice(ALNUM_HYPHEN) for _ in range(middle_len))
    end = r.choice(ALNUM)
    return (start + middle + end).lower()


def long_label(r: random.Random, length: int) -> str:
    length = max(1, min(63, length))
    if length == 1:
        return r.choice(string.ascii_lowercase + string.digits)
    start = r.choice(ALNUM)
    end = r.choice(ALNUM)
    middle = ''.join(r.choice(ALNUM_HYPHEN) for _ in range(length - 2))
    return (start + middle + end).lower()


def build_domain(r: random.Random) -> str:
    choice = r.random()
    if choice < 0.18:
        return r.choice(COMMON_HOSTS)
    if choice < 0.30:
        # single label host
        return rand_label(r, 1, r.randint(3, 15))
    if choice < 0.45:
        # typical domain
        name = rand_label(r, 3, 12)
        tld = r.choice(COMMON_TLDS)
        return f"{name}.{tld}"
    if choice < 0.60:
        # multi-level subdomain depth 3-5
        depth = r.randint(3, 5)
        labels = [rand_label(r, 1, r.randint(3, 12)) for _ in range(depth - 1)]
        labels.append(r.choice(COMMON_TLDS))
        return '.'.join(labels)
    if choice < 0.72:
        # include a long label near 63 chars
        L = r.randint(55, 63)
        lbl = long_label(r, L)
        tld = r.choice(COMMON_TLDS)
        return f"{lbl}.{tld}"
    if choice < 0.84:
        # long total length but within 253; guard randint bounds carefully
        labels: List[str] = []
        remaining = r.randint(200, 245)
        # Build labels until nearing remaining; ensure we always have room for dot and final TLD (~3)
        while remaining > 15 and len(labels) < 10:
            # next label length upper bound cannot exceed remaining - safety_margin
            safety_margin = 7  # dot + minimal next label + minimal tld allowance
            upper = min(63, max(10, remaining - safety_margin))
            lower = 10 if upper >= 10 else 1
            if lower > upper:
                break
            L = r.randint(lower, upper)
            labels.append(long_label(r, L))
            remaining -= (L + 1)
        labels.append(r.choice(COMMON_TLDS))
        domain = '.'.join(labels)
        # Enforce 253 max by trimming labels if necessary
        if len(domain) > 253:
            # remove from the front until within limit
            while len(domain) > 253 and len(labels) > 1:
                labels.pop(0)
                domain = '.'.join(labels)
            if len(domain) > 253:
                domain = domain[:253].rstrip('.')
        return domain
    if choice < 0.92:
        # punycode/IDN-like
        base = r.choice(PUNY_EXAMPLES)
        if r.random() < 0.5:
            sub = rand_label(r, 3, 10)
            return f"{sub}.{base}"
        return base
    else:
        # absolute FQDN with trailing dot
        core = build_domain(r)
        if core.endswith('.'):
            return core
        return core + '.'


def sprinkle_case(r: random.Random, s: str) -> str:
    out_chars = []
    for ch in s:
        if 'a' <= ch <= 'z' and r.random() < 0.3:
            out_chars.append(ch.upper())
        elif 'A' <= ch <= 'Z' and r.random() < 0.3:
            out_chars.append(ch.lower())
        else:
            out_chars.append(ch)
    return ''.join(out_chars)


def clamp_total(buf: bytes) -> bytes:
    return buf[:MAX_TOTAL]


def generate(seed: int) -> bytes:
    r = random.Random(seed)

    curated = [
        "localhost",
        "example.com",
        "EXAMPLE.local",
        "sub.domain.example",
        "xn--d1acpjx3f",
        "b\u00fccher.de".encode('idna').decode('ascii'),  # xn--bcher-kva.de
    ]

    if r.random() < 0.35:
        s = r.choice(curated)
    else:
        s = build_domain(r)
        s = sprinkle_case(r, s)

    data = s.encode('ascii', errors='ignore') + b"\x00"
    return clamp_total(data)
